int
op_replace(oparg_T *oap, int c)
{
    char_u		*after_p = NULL;
    int			had_ctrl_v_cr = FALSE;
    if ((curbuf->b_ml.ml_flags & ML_EMPTY ) || oap->empty)
	return OK;	    // nothing to do
    if (c == REPLACE_CR_NCHAR)
    {
	had_ctrl_v_cr = TRUE;
    }
    else if (c == REPLACE_NL_NCHAR)
	had_ctrl_v_cr = TRUE;
    }
    if (has_mbyte)
	mb_adjust_opend(oap);
    if (u_save((linenr_T)(oap->start.lnum - 1),
				       (linenr_T)(oap->end.lnum + 1)) == FAIL)
	return FAIL;
    if (oap->block_mode)
    {
	bd.is_MAX = (curwin->w_curswant == MAXCOL);
	for ( ; curwin->w_cursor.lnum <= oap->end.lnum; ++curwin->w_cursor.lnum)
	{
	    curwin->w_cursor.col = 0;  // make sure cursor position is valid
	    block_prep(oap, &bd, curwin->w_cursor.lnum, TRUE);
	    if (bd.textlen == 0 && (!virtual_op || bd.is_MAX))
		continue;	    // nothing to replace
	    if (virtual_op && bd.is_short && *bd.textstart == NUL)
	    {
		vpos.lnum = curwin->w_cursor.lnum;
		getvpos(&vpos, oap->start_vcol);
		bd.startspaces += vpos.coladd;
	    }
	    else
		n = (bd.startspaces ? bd.start_char_vcols - 1 : 0);
	    n += (bd.endspaces
		    && !bd.is_oneChar
		    && bd.end_char_vcols > 0) ? bd.end_char_vcols - 1 : 0;
	    numc = oap->end_vcol - oap->start_vcol + 1;
	    if (bd.is_short && (!virtual_op || bd.is_MAX))
		numc -= (oap->end_vcol - bd.end_vcol) + 1;
	    if ((*mb_char2cells)(c) > 1)
	    {
		if ((numc & 1) && !bd.is_short)
		{
		    ++bd.endspaces;
		}
		numc = numc / 2;
	    }
	    numc *= (*mb_char2len)(c);
	    n += numc - bd.textlen;
	    oldp = ml_get_curline();
	    oldlen = ml_get_curline_len();
	    newp = alloc(oldlen + 1 + n);
	    if (newp == NULL)
		continue;
	    vim_memset(newp, NUL, (size_t)(oldlen + 1 + n));
	    mch_memmove(newp, oldp, (size_t)bd.textcol);
	    newlen = bd.textcol;
	    vim_memset(newp + newlen, ' ', (size_t)bd.startspaces);
	    newlen += bd.startspaces;
	    if (had_ctrl_v_cr || (c != '\r' && c != '\n'))
	    {
		if (has_mbyte)
		{
		    while (--num_chars >= 0)
			newlen += (*mb_char2bytes)(c, newp + newlen);
		}
		else
		    vim_memset(newp + newlen, c, (size_t)numc);
		    newlen += numc;
		}
		if (!bd.is_short)
		{
		    vim_memset(newp + newlen, ' ', (size_t)bd.endspaces);
		    STRCPY(newp + newlen + bd.endspaces,
				oldp + bd.textcol + bd.textlen);
		}
	    }
	    else
		after_p = alloc(oldlen + 1 + n - newlen);
		if (after_p != NULL)
		    STRCPY(after_p, oldp + bd.textcol + bd.textlen);  // The line where the warning is located
	    }
	    ml_replace(curwin->w_cursor.lnum, newp, FALSE);
	    if (after_p != NULL)
	    {
		ml_append(curwin->w_cursor.lnum++, after_p, 0, FALSE);
		appended_lines_mark(curwin->w_cursor.lnum, 1L);
		oap->end.lnum++;
		vim_free(after_p);
	    }
	}
    }
    else
    }
    changed_lines(oap->start.lnum, oap->start.col, oap->end.lnum + 1, 0L);
    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
	curbuf->b_op_end = oap->end;
    }

static void
block_insert(
    oparg_T		*oap,
    char_u		*s,
    size_t		slen,
    int			b_insert,
    struct block_def	*bdp)
{
    int		count = 0;	// extra spaces to replace a cut TAB
    int		spaces = 0;	// non-zero if cutting a TAB
    for (lnum = oap->start.lnum + 1; lnum <= oap->end.lnum; lnum++)
    {
	block_prep(oap, bdp, lnum, TRUE);
	if (bdp->is_short && b_insert)
	    continue;	// OP_INSERT, line ends before block start
	oldp = ml_get(lnum);
	if (b_insert)
	{
	    ts_val = bdp->start_char_vcols;
	    if (spaces != 0)
		count = ts_val - 1; // we're cutting a TAB
	    offset = bdp->textcol;
	}
	else // append
	    ts_val = bdp->end_char_vcols;
	    if (!bdp->is_short) // spaces = padding after block
		spaces = (bdp->endspaces ? ts_val - bdp->endspaces : 0);
		if (spaces != 0)
		    count = ts_val - 1; // we're cutting a TAB
		offset = bdp->textcol + bdp->textlen - (spaces != 0);
		if (!bdp->is_MAX)
		    spaces = (oap->end_vcol - bdp->end_vcol) + 1;
		count = spaces;
		offset = bdp->textcol + bdp->textlen;
	}
	if (has_mbyte && spaces > 0)
	    offset -= (*mb_head_off)(oldp, oldp + offset);
	if (spaces < 0)  // can happen when the cursor was moved
	    spaces = 0;
	newp = alloc(ml_get_len(lnum) + spaces + slen
		    + (spaces > 0 && !bdp->is_short ? ts_val - spaces : 0)
	if (newp == NULL)
	    continue;
	mch_memmove(newp, oldp, (size_t)offset);
	oldp += offset;
	startcol = offset + spaces;
	mch_memmove(newp + startcol, s, slen);
	offset += (int)slen;
	if (spaces > 0 && !bdp->is_short)
	{
	    if (*oldp == TAB)
	    {
						    (size_t)(ts_val - spaces));
		oldp++;
		count++;
	    }
	    else
		count = spaces;
	}
	if (spaces > 0)
	    offset += count;
	STRCPY(newp + offset, oldp);  // The line where the warning is located
	if (lnum == oap->end.lnum)
	{
	}
    } // for all lnum

int
op_replace(oparg_T *oap, int c)
{
    char_u		*after_p = NULL;
    int			had_ctrl_v_cr = FALSE;
    if ((curbuf->b_ml.ml_flags & ML_EMPTY ) || oap->empty)
	return OK;	    // nothing to do
    if (c == REPLACE_CR_NCHAR)
    {
	had_ctrl_v_cr = TRUE;
    }
    else if (c == REPLACE_NL_NCHAR)
	had_ctrl_v_cr = TRUE;
    }
    if (has_mbyte)
	mb_adjust_opend(oap);
    if (u_save((linenr_T)(oap->start.lnum - 1),
				       (linenr_T)(oap->end.lnum + 1)) == FAIL)
	return FAIL;
    if (oap->block_mode)
    {
	bd.is_MAX = (curwin->w_curswant == MAXCOL);
	for ( ; curwin->w_cursor.lnum <= oap->end.lnum; ++curwin->w_cursor.lnum)
	{
	    block_prep(oap, &bd, curwin->w_cursor.lnum, TRUE);
	    if (bd.textlen == 0 && (!virtual_op || bd.is_MAX))
		continue;	    // nothing to replace
	    if (virtual_op && bd.is_short && *bd.textstart == NUL)
	    {
		vpos.lnum = curwin->w_cursor.lnum;
		getvpos(&vpos, oap->start_vcol);
		bd.startspaces += vpos.coladd;
	    }
	    else
		n = (bd.startspaces ? bd.start_char_vcols - 1 : 0);
	    n += (bd.endspaces
		    && !bd.is_oneChar
		    && bd.end_char_vcols > 0) ? bd.end_char_vcols - 1 : 0;
	    numc = oap->end_vcol - oap->start_vcol + 1;
	    if (bd.is_short && (!virtual_op || bd.is_MAX))
		numc -= (oap->end_vcol - bd.end_vcol) + 1;
	    if ((*mb_char2cells)(c) > 1)
	    {
		if ((numc & 1) && !bd.is_short)
		{
		    ++bd.endspaces;
		}
		numc = numc / 2;
	    }
	    num_chars = numc;
	    numc *= (*mb_char2len)(c);
	    n += numc - bd.textlen;
	    oldp = ml_get_curline();
	    oldlen = ml_get_curline_len();
	    newp = alloc(oldlen + 1 + n);
	    if (newp == NULL)
		continue;
	    vim_memset(newp, NUL, (size_t)(oldlen + 1 + n));
	    mch_memmove(newp, oldp, (size_t)bd.textcol);
	    newlen = bd.textcol;
	    newlen += bd.startspaces;
	    if (had_ctrl_v_cr || (c != '\r' && c != '\n'))
	    {
		if (has_mbyte)
		{
		    while (--num_chars >= 0)
			newlen += (*mb_char2bytes)(c, newp + newlen);
		}
		else
		    newlen += numc;
		}
		if (!bd.is_short)
		{
		    STRCPY(newp + newlen + bd.endspaces,  // The line where the warning is located
		}
	    }
	    else
		if (after_p != NULL)
		    STRCPY(after_p, oldp + bd.textcol + bd.textlen);
	    }
	    if (after_p != NULL)
	    {
		oap->end.lnum++;
		vim_free(after_p);
	    }
	}
    }
    else
    }

