char_u *
transstr(char_u *s)
{
    if (has_mbyte)
    {
	len = 0;
	p = s;
	while (*p != NUL)
	{
	    if ((l = (*mb_ptr2len)(p)) > 1)
	    {
		p += l;
		if (vim_isprintc(c))
		    len += l;
		else
		    len += (int)STRLEN(hexbuf);
		}
	    }
	    else
		l = byte2cells(*p++);
		if (l > 0)
		    len += l;
		    len += 4;	// illegal byte sequence
	    }
	}
	res = alloc(len + 1);
    }
    else
	res = alloc(vim_strsize(s) + 1);
    if (res == NULL)
	return NULL;
    *res = NUL;
    p = s;
    while (*p != NUL)
    {
	if (has_mbyte && (l = (*mb_ptr2len)(p)) > 1)
	{
	    c = (*mb_ptr2char)(p);
	    if (vim_isprintc(c))
		STRNCAT(res, p, l);	// append printable multi-byte char
	    else
		transchar_hex(res + STRLEN(res), c);
	    p += l;
	}
	else
	    STRCAT(res, transchar_byte(*p++));  // The line where the warning is located
    }
    return res;

