			if (typed == 'l')
			{
			    subflags.do_all = FALSE;
			    line2 = lnum;
			}
			if (typed == 'a')
			{
			    subflags.do_ask = FALSE;
			}
			if (typed == Ctrl_E)
			    scrollup_clamp();
			else if (typed == Ctrl_Y)
			    scrolldown_clamp();
		    }
		    if (vim_strchr(p_cpo, CPO_UNDO) != NULL)
			--no_u_sync;
		    if (typed == 'n')
		    {
			if (nmatch > 1)
			{
			    matchcol = (colnr_T)STRLEN(sub_firstline);
			    skip_match = TRUE;
			}
		    }
		    if (got_quit)
			goto skip;
		}
		sublen = vim_regsub_multi(&regmatch,
				    sub_firstlnum - regmatch.startpos[0].lnum,
			       REGSUB_BACKSLASH
		if (nmatch > curbuf->b_ml.ml_line_count - sub_firstlnum + 1)
		{
		    nmatch = curbuf->b_ml.ml_line_count - sub_firstlnum + 1;
		    skip_match = TRUE;
		    if (nmatch < 0)
			goto skip;
		}
		if (nmatch == 1)
		{
		    p1 = sub_firstline;
		}
		else
		    linenr_T	lastlnum = sub_firstlnum + nmatch - 1;
		    p1 = ml_get(lastlnum);
		    nmatch_tl += nmatch - 1;
		}
		copy_len = regmatch.startpos[0].col - copycol;
		needed_len = copy_len + ((unsigned)STRLEN(p1)
		if (new_start == NULL)
		{
		    new_start_len = needed_len + 50;
		    if ((new_start = alloc_clear(new_start_len)) == NULL)
			goto outofmem;
		    *new_start = NUL;
		}
		else
		    len = (unsigned)STRLEN(new_start);
		    needed_len += len;
		    if (needed_len > (int)new_start_len)
			new_start_len = needed_len + 50;
			if ((p1 = alloc_clear(new_start_len)) == NULL)
			mch_memmove(p1, new_start, (size_t)(len + 1));
			new_start = p1;
		}
		mch_memmove(new_end, sub_firstline + copycol, (size_t)copy_len);
		new_end += copy_len;
		if ((int)new_start_len - copy_len < sublen)
		    sublen = new_start_len - copy_len - 1;
		(void)vim_regsub_multi(&regmatch,
				    sub_firstlnum - regmatch.startpos[0].lnum,
				      REGSUB_COPY | REGSUB_BACKSLASH
		did_sub = TRUE;
		if (nmatch > 1)
		{
		    sub_firstlnum += nmatch - 1;
		    sub_firstline = vim_strnsave(ml_get(sub_firstlnum),
						    ml_get_len(sub_firstlnum));
		    if (sub_firstlnum <= line2)
			do_again = TRUE;
		    else
			subflags.do_all = FALSE;
		}
		copycol = regmatch.endpos[0].col;
		if (skip_match)
		{
		    sub_firstline = vim_strsave((char_u *)"");
		    copycol = 0;
		}
		for (p1 = new_end; *p1; ++p1)
		{
		    if (p1[0] == '\\' && p1[1] != NUL)  // remove backslash
		    {
			STRMOVE(p1, p1 + 1);
		    }
		    else if (*p1 == CAR)
			if (u_inssub(lnum) == OK)   // prepare for undo
			    colnr_T	plen = (colnr_T)(p1 - new_start + 1);
			    *p1 = NUL;		    // truncate up to the CR
			    ml_append(lnum - 1, new_start, plen, FALSE);
				appended_lines(lnum - 1, 1L);
				if (first_line == 0)
				    first_line = lnum;
			    ++sub_firstlnum;
			    ++lnum;
			    ++line2;
			    ++curwin->w_cursor.lnum;
			    STRMOVE(new_start, p1 + 1);
			    p1 = new_start - 1;
			p1 += (*mb_ptr2len)(p1) - 1;
		}
		lastone = (skip_match
			|| lnum > line2
			|| !(subflags.do_all || do_again)
			|| (sub_firstline[matchcol] == NUL && nmatch <= 1
					 && !re_multiline(regmatch.regprog)));
		nmatch = -1;
		if (lastone
			|| nmatch_tl > 0
			|| (nmatch = vim_regexec_multi(&regmatch, curwin,
			|| regmatch.startpos[0].lnum > 0)
		{
		    if (new_start != NULL)
		    {
			STRCAT(new_start, sub_firstline + copycol);  // The line where the warning is located
			matchcol = (colnr_T)STRLEN(sub_firstline) - matchcol;
			prev_matchcol = (colnr_T)STRLEN(sub_firstline)
			if (u_savesub(lnum) != OK)
			    break;
			ml_replace(lnum, new_start, TRUE);
			if (nmatch_tl > 0)
			{
			    ++lnum;
			    if (u_savedel(lnum, nmatch_tl) != OK)
				break;
			    for (i = 0; i < nmatch_tl; ++i)
				ml_delete(lnum);
			    mark_adjust(lnum, lnum + nmatch_tl - 1,
			    if (subflags.do_ask)
				deleted_lines(lnum, nmatch_tl);
			    --lnum;
			    line2 -= nmatch_tl; // nr of lines decreases
			    nmatch_tl = 0;
			}
			if (subflags.do_ask)
			    changed_bytes(lnum, 0);
			else
			    if (first_line == 0)
				first_line = lnum;
			    last_line = lnum + 1;
			}
			sub_firstlnum = lnum;
			sub_firstline = new_start;
			new_start = NULL;
			matchcol = (colnr_T)STRLEN(sub_firstline) - matchcol;
			prev_matchcol = (colnr_T)STRLEN(sub_firstline)
			copycol = 0;
		    }
		    if (nmatch == -1 && !lastone)
			nmatch = vim_regexec_multi(&regmatch, curwin, curbuf,
					  sub_firstlnum, matchcol, NULL);
		    if (nmatch <= 0)
		    {
			if (nmatch == -1)
			    lnum -= regmatch.startpos[0].lnum;
		    }
		}
	    }
	    if (did_sub)
		++sub_nlines;
	    vim_free(new_start);	// for when substitute was cancelled
	    VIM_CLEAR(sub_firstline);	// free the copy of the original line
	}
	line_breakcheck();
    }
    if (first_line != 0)
    {
	i = curbuf->b_ml.ml_line_count - old_line_count;
	changed_lines(first_line, 0, last_line - i, i);
    }
    vim_free(sub_firstline); // may have to free allocated copy of the line
    if (sub_nsubs > start_nsubs)
    {
	if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
	{
	    curbuf->b_op_end.lnum = line2;
	}
	if (!global_busy)
	{
	}
	else
	    global_need_beginline = TRUE;
	if (subflags.do_print)
	    print_line(curwin->w_cursor.lnum,
					 subflags.do_number, subflags.do_list);
    }
    else if (!global_busy)
    }
    vim_regfree(regmatch.regprog);

if (result == NULL)
	return NULL;
    for (p = result; *p; )
    {
	if (STRNCMP(p, "<sfile>", 7) != 0)
	    ++p;
	else
	    repl = eval_vars(p, result, &srclen, NULL, &errormsg, NULL, TRUE);
	    if (errormsg != NULL)
	    if (repl == NULL)		// no match (cannot happen)
	    repllen = STRLEN(repl);
	    resultlen += repllen - srclen;
	    newres = alloc(resultlen + 1);
	    if (newres == NULL)
	    len = p - result;
	    mch_memmove(newres, result, len);
	    STRCPY(newres + len, repl);  // The line where the warning is located
	    vim_free(repl);
	    result = newres;
	}
    }

void
ex_sort(exarg_T *eap)
{
    long	maxlen = 0;
    size_t	count = (size_t)(eap->line2 - eap->line1 + 1);
    int		unique = FALSE;
    int		sort_what = 0;
    int		format_found = 0;
    if (count <= 1)
	return;
    if (u_save((linenr_T)(eap->line1 - 1), (linenr_T)(eap->line2 + 1)) == FAIL)
	return;
    regmatch.regprog = NULL;
    nrs = ALLOC_MULT(sorti_T, count);
    if (nrs == NULL)
	goto sortend;
    sort_flt = 0;
    for (p = eap->arg; *p != NUL; ++p)
    {
	if (VIM_ISWHITE(*p))
	    ;
	else if (*p == 'i')
	else if (*p == 'l')
	else if (*p == 'r')
	else if (*p == 'n')
	    ++format_found;
	else if (*p == 'f')
	    sort_flt = 1;
	    ++format_found;
	else if (*p == 'b')
	    sort_what = STR2NR_BIN + STR2NR_FORCE;
	    ++format_found;
	else if (*p == 'o')
	    sort_what = STR2NR_OCT + STR2NR_FORCE;
	    ++format_found;
	else if (*p == 'x')
	    sort_what = STR2NR_HEX + STR2NR_FORCE;
	    ++format_found;
	else if (*p == 'u')
	    unique = TRUE;
	else if (*p == '"')	// comment start
	else if (eap->nextcmd == NULL && check_nextcmd(p) != NULL)
	else if (!ASCII_ISALPHA(*p) && regmatch.regprog == NULL)
	    s = skip_regexp_err(p + 1, *p, TRUE);
	    if (s == NULL)
	    *s = NUL;
	    if (s == p + 1)
		if (last_search_pat() == NULL)
		regmatch.regprog = vim_regcomp(last_search_pat(), RE_MAGIC);
		regmatch.regprog = vim_regcomp(p + 1, RE_MAGIC);
	    if (regmatch.regprog == NULL)
	    regmatch.rm_ic = p_ic;
	}
    }
    if (format_found > 1)
    {
    }
    sort_nr += sort_what;
    for (lnum = eap->line1; lnum <= eap->line2; ++lnum)
    {
	s = ml_get(lnum);
	if (maxlen < len)
	    maxlen = len;
	if (regmatch.regprog != NULL && vim_regexec(&regmatch, s, 0))
	{
	}
	else
	    if (regmatch.regprog != NULL)
		end_col = 0;
	if (sort_nr || sort_flt)
	{
	    p = s + start_col;
	    if (sort_nr)
	    {
		if (sort_what & STR2NR_HEX)
		    s = skiptohex(p);
		else if (sort_what & STR2NR_BIN)
		    s = skiptobin(p);
		    s = skiptodigit(p);
		if (s > p && s[-1] == '-')
		    --s;  // include preceding negative sign
		if (*s == NUL)
		{
		}
		else
		    vim_str2nr(s, NULL, NULL, sort_what,
		}
	    }
	    else
		s = skipwhite(p);
		if (*s == '+')
		    s = skipwhite(s + 1);
		if (*s == NUL)
						      strtod((char *)s, NULL);
	    }
	}
	else
	}
	nrs[lnum - eap->line1].lnum = lnum;
	if (regmatch.regprog != NULL)
	    fast_breakcheck();
	if (got_int)
	    goto sortend;
    }
    sortbuf1 = alloc(maxlen + 1);
    if (sortbuf1 == NULL)
	goto sortend;
    if (sortbuf2 == NULL)
	goto sortend;
    qsort((void *)nrs, count, sizeof(sorti_T), sort_compare);
    if (sort_abort)
	goto sortend;
    lnum = eap->line2;
    for (i = 0; i < count; ++i)
    {
	linenr_T get_lnum = nrs[eap->forceit ? count - i - 1 : i].lnum;
	if (get_lnum + ((linenr_T)count - 1) != lnum)
	    change_occurred = TRUE;
	s = ml_get(get_lnum);
	if (!unique || i == 0 || string_compare(s, sortbuf1) != 0)
	{
	    STRCPY(sortbuf1, s);  // The line where the warning is located
	    if (ml_append(lnum++, sortbuf1, (colnr_T)0, FALSE) == FAIL)
		break;
	}
	fast_breakcheck();
	if (got_int)
	    goto sortend;
    }
    if (i == count)
	for (i = 0; i < count; ++i)
	    ml_delete(eap->line1);
    else
	count = 0;
    deleted = (long)(count - (lnum - eap->line2));
    if (deleted > 0)
    {
	mark_adjust(eap->line2 - deleted, eap->line2, (long)MAXLNUM, -deleted);
	msgmore(-deleted);
    }
    else if (deleted < 0)
	mark_adjust(eap->line2, MAXLNUM, -deleted, 0L);
    if (change_occurred || deleted != 0)
	changed_lines(eap->line1, 0, eap->line2 + 1, -deleted);
    curwin->w_cursor.lnum = eap->line1;
    beginline(BL_WHITE | BL_FIX);
    vim_free(sortbuf1);

static char_u *
repl_cmdline(
    exarg_T	*eap,
    char_u	*src,
    size_t	srclen,
    char_u	*repl,
    char_u	**cmdlinep)
{
    repllen = STRLEN(repl);
    taillen = STRLEN(src + srclen);
    i = (src - *cmdlinep) + repllen + taillen + 3;
    if (eap->nextcmd != NULL)
	i += STRLEN(eap->nextcmd);	// add space for next command
    if ((new_cmdline = alloc(i)) == NULL)
	return NULL;			// out of memory!
    new_cmdlinelen = src - *cmdlinep;	// length of part before replacement
    mch_memmove(new_cmdline, *cmdlinep, new_cmdlinelen);
    mch_memmove(new_cmdline + new_cmdlinelen, repl, repllen);
    new_cmdlinelen += repllen;		// remember the end of the string
    STRCPY(new_cmdline + new_cmdlinelen, src + srclen);  // The line where the warning is located

static char_u *
repl_cmdline(
    exarg_T	*eap,
    char_u	*src,
    size_t	srclen,
    char_u	*repl,
    char_u	**cmdlinep)
{
    repllen = STRLEN(repl);
    taillen = STRLEN(src + srclen);
    i = (src - *cmdlinep) + repllen + taillen + 3;
    if (eap->nextcmd != NULL)
	i += STRLEN(eap->nextcmd);	// add space for next command
    if ((new_cmdline = alloc(i)) == NULL)
	return NULL;			// out of memory!
    new_cmdlinelen = src - *cmdlinep;	// length of part before replacement
    mch_memmove(new_cmdline, *cmdlinep, new_cmdlinelen);
    mch_memmove(new_cmdline + new_cmdlinelen, repl, repllen);
    new_cmdlinelen += repllen;		// remember the end of the string
    if (eap->nextcmd != NULL)		// append next command
    {
	new_cmdlinelen += taillen + 1;
	STRCPY(new_cmdline + new_cmdlinelen, eap->nextcmd);  // The line where the warning is located
    }

static int	if_level = 0;		// depth in :if
    static char_u *
do_one_cmd(
    char_u	**cmdlinep,
    int		flags,
#ifdef FEAT_EVAL
    cstack_T	*cstack,
#endif
    char_u	*(*fgetline)(int, void *, int, getline_opt_T),
    void	*cookie)		// argument for fgetline()
{
    char	*errormsg = NULL;	// error message
    int		starts_with_colon = FALSE;
    int		sourcing = flags & DOCMD_VERBOSE;
    int		did_append_cmd = FALSE;
    CLEAR_FIELD(ea);
    ea.line1 = 1;
    ea.line2 = 1;
    if (quitmore
	    && !getline_equal(fgetline, cookie, getnextac))
	--quitmore;
    if ((*cmdlinep)[0] == '#' && (*cmdlinep)[1] == '!')
	goto doend;
    ea.cmd = *cmdlinep;
    ea.cmdlinep = cmdlinep;
    ea.ea_getline = fgetline;
    ea.cookie = cookie;
    if (parse_command_modifiers(&ea, &errormsg, &cmdmod, FALSE) == FAIL)
	goto doend;
    after_modifier = ea.cmd;
    ea.skip = (if_level > 0);
    cmd = ea.cmd;
    int vim9script = in_vim9script();
    if (vim9script && (flags & DOCMD_RANGEOK) == 0)
    {
	may_have_range = FALSE;
	for (p = ea.cmd; p >= *cmdlinep; --p)
	{
	    if (*p == ':')
		may_have_range = TRUE;
	    if (p < ea.cmd && !VIM_ISWHITE(*p))
		break;
	}
    }
    else
	may_have_range = TRUE;
    if (may_have_range)
	ea.cmd = skip_range(ea.cmd, TRUE, NULL);
    if (vim9script && !may_have_range)
    {
	if (ea.cmd == cmd + 1 && *cmd == '$')
	    --ea.cmd;
	p = find_ex_command(&ea, NULL, NULL, NULL);
	if (ea.cmdidx == CMD_SIZE)
	{
	    char_u *ar = skip_range(ea.cmd, TRUE, NULL);
	    if (ar > ea.cmd && !ea.skip)
	    {
	    }
	}
    }
    else
	p = find_ex_command(&ea, NULL, NULL, NULL);
    ea.cmd = cmd;
    if (!IS_USER_CMDIDX(ea.cmdidx))
    {
	if (ea.cmdidx != CMD_SIZE)
	    ea.addr_type = cmdnames[(int)ea.cmdidx].cmd_addr_type;
	else
	    ea.addr_type = ADDR_LINES;
	if (ea.cmdidx == CMD_wincmd && p != NULL)
	    get_wincmd_addr_type(skipwhite(p), &ea);
    }
    if (!may_have_range)
	ea.line1 = ea.line2 = default_address(&ea);
    else if (parse_cmd_address(&ea, &errormsg, FALSE) == FAIL)
	goto doend;
    ea.cmd = skipwhite(ea.cmd);
    while (*ea.cmd == ':')
	ea.cmd = skipwhite(ea.cmd + 1);
    if (*ea.cmd == NUL || comment_start(ea.cmd, starts_with_colon)
			       || (ea.nextcmd = check_nextcmd(ea.cmd)) != NULL)
    {
	if (ea.skip)	    // skip this if inside :if
	    goto doend;
	errormsg = ex_range_without_command(&ea);
    }
    if (p != NULL && ea.cmdidx == CMD_SIZE && !ea.skip
	    && ASCII_ISUPPER(*ea.cmd)
	    && has_cmdundefined())
    {
	p = ea.cmd;
	while (ASCII_ISALNUM(*p))
	    ++p;
	p = vim_strnsave(ea.cmd, p - ea.cmd);
	ret = apply_autocmds(EVENT_CMDUNDEFINED, p, p, TRUE, NULL);
	p = (ret
		) ? find_ex_command(&ea, NULL, NULL, NULL) : ea.cmd;
    }
    if (p == NULL)
    {
	if (!ea.skip)
	    errormsg = _(e_ambiguous_use_of_user_defined_command);
    }
    if (*p == '!' && ea.cmd[1] == 0151 && ea.cmd[0] == 78
	    && !IS_USER_CMDIDX(ea.cmdidx))
    {
	errormsg = uc_fun_cmd();
    }
    if (ea.cmdidx == CMD_SIZE)
    {
	if (!ea.skip)
	{
	    STRCPY(IObuff, _(e_not_an_editor_command));
	    if (!sourcing)
	    {
		if (after_modifier != NULL)
		    append_command(after_modifier);
		else
		    append_command(*cmdlinep);
		did_append_cmd = TRUE;
	    }
	    errormsg = (char *)IObuff;
	}
    }
    ni = (!IS_USER_CMDIDX(ea.cmdidx)
    if (ea.cmdidx == CMD_if)
    if (if_level)
    if (*p == '!' && ea.cmdidx != CMD_substitute
	    && ea.cmdidx != CMD_smagic && ea.cmdidx != CMD_snomagic)
    {
	++p;
	ea.forceit = TRUE;
    }
    else
	ea.forceit = FALSE;
    if (!IS_USER_CMDIDX(ea.cmdidx))
	ea.argt = (long)cmdnames[(int)ea.cmdidx].cmd_argt;
    if (!ea.skip)
    {
	if (restricted != 0 && (ea.argt & EX_RESTRICT))
	{
	    errormsg = _(e_command_not_allowed_in_rvim);
	}
	if (!curbuf->b_p_ma && (ea.argt & EX_MODIFY))
	{
	    errormsg = _(e_cannot_make_changes_modifiable_is_off);
	}
	if (!IS_USER_CMDIDX(ea.cmdidx))
	{
	    if (cmdwin_type != 0 && !(ea.argt & EX_CMDWIN))
	    {
		errormsg = _(e_invalid_in_cmdline_window);
	    }
	    if (text_locked() && !(ea.argt & EX_LOCK_OK))
	    {
		errormsg = _(get_text_locked_msg());
	    }
	}
	if (!(ea.argt & (EX_CMDWIN | EX_LOCK_OK))
		&& ea.cmdidx != CMD_checktime
		&& ea.cmdidx != CMD_edit
		&& ea.cmdidx != CMD_file
		&& !IS_USER_CMDIDX(ea.cmdidx)
		&& curbuf_locked())
	    goto doend;
	if (!ni && !(ea.argt & EX_RANGE) && ea.addr_count > 0)
	{
	    errormsg = _(e_no_range_allowed);
	}
    }
    if (!ni && !(ea.argt & EX_BANG) && ea.forceit)
    {
	errormsg = _(e_no_bang_allowed);
    }
    if (!ea.skip && !ni && (ea.argt & EX_RANGE))
    {
	if (!global_busy && ea.line1 > ea.line2)
	{
	    if (msg_silent == 0)
	    {
		if (sourcing || exmode_active)
		{
		    errormsg = _(e_backwards_range_given);
		}
		if (ask_yesno((char_u *)
			_("Backwards range given, OK to swap"), FALSE) != 'y')
		    goto doend;
	    }
	    lnum = ea.line1;
	    ea.line1 = ea.line2;
	    ea.line2 = lnum;
	}
	if ((errormsg = invalid_range(&ea)) != NULL)
	    goto doend;
    }
    if ((ea.addr_type == ADDR_OTHER) && ea.addr_count == 0)
	ea.line2 = 1;
    correct_range(&ea);
    if (ea.cmdidx == CMD_bang)
	ea.arg = p;
    else
	ea.arg = skipwhite(p);
    if (ea.cmdidx == CMD_file && *ea.arg != NUL && curbuf_locked())
	goto doend;
    if (ea.argt & EX_ARGOPT)
	while (ea.arg[0] == '+' && ea.arg[1] == '+')
	    if (getargopt(&ea) == FAIL && !ni)
		errormsg = _(e_invalid_argument);
	    }
    if (ea.cmdidx == CMD_write || ea.cmdidx == CMD_update)
    {
	if (*ea.arg == '>')			// append
	{
	    if (*++ea.arg != '>')		// typed wrong
	    {
		errormsg = _(e_use_w_or_w_gt_gt);
	    }
	    ea.arg = skipwhite(ea.arg + 1);
	    ea.append = TRUE;
	}
	else if (*ea.arg == '!' && ea.cmdidx == CMD_write)  // :w !filter
	    ++ea.arg;
	    ea.usefilter = TRUE;
	}
    }
    if (ea.cmdidx == CMD_read)
    {
	if (ea.forceit)
	{
	    ea.usefilter = TRUE;		// :r! filter if ea.forceit
	    ea.forceit = FALSE;
	}
	else if (*ea.arg == '!')		// :r !filter
	    ++ea.arg;
	    ea.usefilter = TRUE;
	}
    }
    if (ea.cmdidx == CMD_lshift || ea.cmdidx == CMD_rshift)
    {
	ea.amount = 1;
	while (*ea.arg == *ea.cmd)		// count number of '>' or '<'
	{
	    ++ea.arg;
	    ++ea.amount;
	}
	ea.arg = skipwhite(ea.arg);
    }
    if ((ea.argt & EX_CMDARG) && !ea.usefilter)
	ea.do_ecmd_cmd = getargcmd(&ea.arg);
    if ((ea.argt & EX_TRLBAR) && !ea.usefilter)
    {
	separate_nextcmd(&ea, FALSE);
    }
    else if (ea.cmdidx == CMD_bang
	    || ea.cmdidx == CMD_terminal
	    || ea.cmdidx == CMD_global
	    || ea.cmdidx == CMD_vglobal
	for (p = ea.arg; *p; ++p)
	    if (*p == '\\' && p[1] == '\n')
		STRMOVE(p, p + 1);
	    else if (*p == '\n' && !(ea.argt & EX_EXPR_ARG))
		ea.nextcmd = p + 1;
    }
    if ((ea.argt & EX_DFLALL) && ea.addr_count == 0)
	address_default_all(&ea);
    if (       (ea.argt & EX_REGSTR)
	    && *ea.arg != NUL
	    && (!IS_USER_CMDIDX(ea.cmdidx) || *ea.arg != '=')
	    && !((ea.argt & EX_COUNT) && VIM_ISDIGIT(*ea.arg)))
    {
	if (*ea.arg == '*' || *ea.arg == '+')
	    errormsg = _(e_invalid_register_name);
	if (valid_yank_reg(*ea.arg, (ea.cmdidx != CMD_put
					      && !IS_USER_CMDIDX(ea.cmdidx))))
	{
	    ea.regname = *ea.arg++;
	    ea.arg = skipwhite(ea.arg);
	}
    }
    if ((ea.argt & EX_COUNT) && VIM_ISDIGIT(*ea.arg)
	    && (!(ea.argt & EX_BUFNAME) || *(p = skipdigits(ea.arg + 1)) == NUL
							  || VIM_ISWHITE(*p)))
    {
	n = getdigits_quoted(&ea.arg);
	ea.arg = skipwhite(ea.arg);
	if (n <= 0 && !ni && (ea.argt & EX_ZEROR) == 0)
	{
	    errormsg = _(e_positive_count_required);
	}
	if (ea.addr_type != ADDR_LINES)	// e.g. :buffer 2, :sleep 3
	{
	    ea.line2 = n;
	    if (ea.addr_count == 0)
		ea.addr_count = 1;
	}
	else
	    ea.line1 = ea.line2;
	    if (ea.line2 >= LONG_MAX - (n - 1))
		ea.line2 = LONG_MAX;  // avoid overflow
		ea.line2 += n - 1;
	    ++ea.addr_count;
	    if (ea.line2 > curbuf->b_ml.ml_line_count)
		ea.line2 = curbuf->b_ml.ml_line_count;
	}
    }
    if (ea.argt & EX_FLAGS)
	get_flags(&ea);
    if (!ni && !(ea.argt & EX_EXTRA) && *ea.arg != NUL
	    && *ea.arg != '"' && (*ea.arg != '|' || (ea.argt & EX_TRLBAR) == 0))
    {
	errormsg = ex_errmsg(e_trailing_characters_str, ea.arg);
    }
    if (!ni && (ea.argt & EX_NEEDARG) && *ea.arg == NUL)
    {
	errormsg = _(e_argument_required);
    }
    if ((ea.argt & EX_XFILE)
	    && expand_filename(&ea, cmdlinep, &errormsg) == FAIL)
	goto doend;
    if ((ea.argt & EX_BUFNAME) && *ea.arg != NUL && ea.addr_count == 0
	    && !IS_USER_CMDIDX(ea.cmdidx))
    {
	ea.line2 = buflist_findpat(ea.arg, p, (ea.argt & EX_BUFUNL) != 0,
	if (ea.line2 < 0)	    // failed
	    goto doend;
	ea.addr_count = 1;
	ea.arg = skipwhite(p);
    }
    if (IS_USER_CMDIDX(ea.cmdidx))
    {
    }
    else
	if (ea.errmsg != NULL)
	    errormsg = ea.errmsg;
    }
    if (errormsg != NULL && *errormsg != NUL && !did_emsg)
    {
	if ((sourcing || !KeyTyped) && !did_append_cmd)
	{
	    if (errormsg != (char *)IObuff)
	    {
		STRCPY(IObuff, errormsg);  // The line where the warning is located
		errormsg = (char *)IObuff;
	    }
	}
	emsg(errormsg);
    }

static int
cmdline_browse_history(
	int	c,
	int	firstc,
	char_u	**curcmdstr,
	size_t	*curcmdstrlen,
	int	histype,
	int	*hiscnt_p,
	expand_T *xp)
{
    int		hiscnt = orig_hiscnt = *hiscnt_p;
    char_u	*lookfor = *curcmdstr;
    size_t	lookforlen = *curcmdstrlen;
    if (get_hislen() == 0 || firstc == NUL)	// no history
	return CMDLINE_NOT_CHANGED;
    if (lookfor == NULL)
    {
	if ((lookfor = vim_strnsave(ccline.cmdbuff, ccline.cmdlen)) == NULL)
	    return CMDLINE_NOT_CHANGED;
	lookfor[ccline.cmdpos] = NUL;
	lookforlen = ccline.cmdpos;
    }
    for (;;)
    {
	if (c == K_UP|| c == K_S_UP || c == Ctrl_P
		|| c == K_PAGEUP || c == K_KPAGEUP)
	{
	    if (hiscnt == get_hislen())	// first time
		hiscnt = *get_hisidx(histype);
	    else if (hiscnt == 0 && *get_hisidx(histype)
		hiscnt = get_hislen() - 1;
	    else if (hiscnt != *get_hisidx(histype) + 1)
		--hiscnt;
		hiscnt = orig_hiscnt;
	    }
	}
	else    // one step forwards
	    if (hiscnt == *get_hisidx(histype))
		hiscnt = get_hislen();
	    if (hiscnt == get_hislen())
		hiscnt = 0;
		++hiscnt;
	}
	if (hiscnt < 0 || get_histentry(histype)[hiscnt].hisstr
		== NULL)
	{
	    hiscnt = orig_hiscnt;
	}
	if ((c != K_UP && c != K_DOWN)
		|| hiscnt == orig_hiscnt
		|| STRNCMP(get_histentry(histype)[hiscnt].hisstr,
		    lookfor, lookforlen) == 0)
	    break;
    }
    if (hiscnt != orig_hiscnt)	// jumped to other entry
    {
	if (hiscnt == get_hislen())
	{
	    p = lookfor;	// back to the old one
	}
	else
	    p = get_histentry(histype)[hiscnt].hisstr;
	    plen = STRLEN(p);
	}
	if (histype == HIST_SEARCH
		&& p != lookfor
		&& (old_firstc = p[plen + 1]) != firstc)
	{
	}
	else
	    if (ccline.cmdbuff == NULL)
	    STRCPY(ccline.cmdbuff, p);  // The line where the warning is located
	}
    }

