static struct lline *coalesce_lines(struct lline *base, int *lenbase,
				    struct lline *newline, int lennew,
				    unsigned long parent, long flags)
{
	struct lline *baseend, *newend = NULL;
	if (!newline)
		return base;
	if (!base) {
	}
	CALLOC_ARRAY(lcs, st_add(origbaselen, 1));
	CALLOC_ARRAY(directions, st_add(origbaselen, 1));
	for (i = 0; i < origbaselen + 1; i++) {
		CALLOC_ARRAY(directions[i], st_add(lennew, 1));
	}
	for (i = 1, baseend = base; i < origbaselen + 1; i++) {
		for (j = 1, newend = newline; j < lennew + 1; j++) {
			if (match_string_spaces(baseend->line, baseend->len,
						newend->line, newend->len, flags)) {
				lcs[i][j] = lcs[i - 1][j - 1] + 1;
				directions[i][j] = MATCH;
			} else if (lcs[i][j - 1] >= lcs[i - 1][j]) {
				directions[i][j] = NEW;
				lcs[i][j] = lcs[i - 1][j];
				directions[i][j] = BASE;
			}
			if (newend->next)
				newend = newend->next;
		}
		if (baseend->next)
			baseend = baseend->next;
	}
	i--;
	j--;
	while (i != 0 || j != 0) {
		if (directions[i][j] == MATCH) {
			baseend->parent_map |= 1<<parent;
			baseend = baseend->prev;
			newend = newend->prev;  // The line where the warning is located
			i--;
			j--;
		} else if (directions[i][j] == NEW) {
			lline = newend;
			if (lline->prev)
				lline->prev->next = lline->next;
				newline = lline->next;
			if (lline->next)
				lline->next->prev = lline->prev;
			newend = lline->prev;
			j--;
			if (baseend) {
				lline->next = baseend->next;
				lline->prev = baseend;
				if (lline->prev)
					lline->prev->next = lline;
				lline->next = base;
				base = lline;
			if (lline->next)
				lline->next->prev = lline;
			baseend = baseend->prev;
			i--;
		}
	}
	newend = newline;
	while (newend) {
		struct lline *lline = newend;
		free(lline);
	}
	return base;

static void prepare_attr_stack(struct index_state *istate,
			       const struct object_id *tree_oid,
			       const char *path, int dirlen,
			       struct attr_stack **stack)
{
