	while ((*stack)->origin) {
		elem = *stack;
		if (namelen <= dirlen &&
		    !strncmp(elem->origin, path, namelen) &&
		    (!namelen || path[namelen] == '/'))
			break;
		*stack = elem->prev;
		attr_stack_free(elem);
	}
	while (pathbuf.len < dirlen) {
		size_t len = pathbuf.len;
		if (len < dirlen && is_dir_sep(path[len]))
			len++;
